"use strict";(globalThis.webpackChunkwebsite||=[]).push([[1851],{7898(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","href":"/positron-sas-extension/","label":"SAS Extension for Positron","docId":"README","unlisted":false},{"type":"link","href":"/positron-sas-extension/matrix","label":"Capabilities by Connection Type","docId":"matrix","unlisted":false},{"type":"link","href":"/positron-sas-extension/installation","label":"Installation","docId":"installation","unlisted":false},{"type":"category","label":"SAS in Posit Workbench","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/positron-sas-extension/Workbench/requirements","label":"Requirements by Scenario","docId":"Workbench/requirements","unlisted":false},{"type":"category","label":"SAS within Positron","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/positron-sas-extension/Workbench/Positron/localInstalled","label":"Local SAS: SAS Installed with Workbench","docId":"Workbench/Positron/localInstalled","unlisted":false},{"type":"link","href":"/positron-sas-extension/Workbench/Positron/remoteSsh","label":"Remote SAS over SSH","docId":"Workbench/Positron/remoteSsh","unlisted":false},{"type":"link","href":"/positron-sas-extension/Workbench/Positron/remoteViya","label":"Remote SAS Viya","docId":"Workbench/Positron/remoteViya","unlisted":false}],"href":"/positron-sas-extension/Workbench/Positron/"},{"type":"category","label":"SAS in Your R and Python Code","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/positron-sas-extension/Workbench/Code/viyaOauth","label":"SAS Viya with OAuth Tokens","docId":"Workbench/Code/viyaOauth","unlisted":false},{"type":"link","href":"/positron-sas-extension/Workbench/Code/local","label":"Local SAS Execution","docId":"Workbench/Code/local","unlisted":false}],"href":"/positron-sas-extension/Workbench/Code/"},{"type":"link","href":"/positron-sas-extension/Workbench/foundations","label":"Across All Scenarios","docId":"Workbench/foundations","unlisted":false}],"href":"/positron-sas-extension/Workbench/"},{"type":"category","label":"Configuring the SAS Extension","collapsible":true,"collapsed":false,"items":[{"type":"category","label":"Profile Definitions and Connection Types","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/viya","label":"SAS Viya Connection Profile","docId":"Configurations/Profiles/viya","unlisted":false},{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/sas9local","label":"SAS 9.4 (local) Connection Profile","docId":"Configurations/Profiles/sas9local","unlisted":false},{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/sas9iom","label":"SAS 9.4 (remote - IOM) Connection Profile","docId":"Configurations/Profiles/sas9iom","unlisted":false},{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/sas9ssh","label":"SAS 9.4 (remote - SSH) Connection Profile","docId":"Configurations/Profiles/sas9ssh","unlisted":false},{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/sas9stdio","label":"SAS 9.4 (local - stdio) Connection Profile","docId":"Configurations/Profiles/sas9stdio","unlisted":false},{"type":"link","href":"/positron-sas-extension/Configurations/Profiles/additional","label":"Additional Profile Settings","docId":"Configurations/Profiles/additional","unlisted":false}],"href":"/positron-sas-extension/Configurations/Profiles/"},{"type":"link","href":"/positron-sas-extension/Configurations/sasLog","label":"SAS Log","docId":"Configurations/sasLog","unlisted":false}],"href":"/positron-sas-extension/Configurations/"},{"type":"category","label":"Features","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/positron-sas-extension/Features/accessContent","label":"Accessing SAS Content","docId":"Features/accessContent","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/accessLibraries","label":"Accessing Libraries and Tables","docId":"Features/accessLibraries","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/accessServer","label":"Accessing SAS Server","docId":"Features/accessServer","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/running","label":"Running SAS Code","docId":"Features/running","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/runningTask","label":"Running SAS Code by Task","docId":"Features/runningTask","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/errorsWarnings","label":"Fixing Errors and Warnings","docId":"Features/errorsWarnings","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/sasCodeEditing","label":"SAS Code Editing Features","docId":"Features/sasCodeEditing","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/sasNotebook","label":"SAS Notebook","docId":"Features/sasNotebook","unlisted":false},{"type":"link","href":"/positron-sas-extension/Features/positron","label":"Positron SAS Extension Features","docId":"Features/positron","unlisted":false}],"href":"/positron-sas-extension/Features/"},{"type":"link","href":"/positron-sas-extension/faq","label":"Frequently Asked Questions","docId":"faq","unlisted":false}]},"docs":{"Configurations/index":{"id":"Configurations/index","title":"Configuring the SAS Extension","description":"Before running SAS code, you must configure the SAS extension to access a SAS 9.4 (remote or local) server or a SAS Viya server. You must license SAS 9.4 or SAS Viya to run SAS code.","sidebar":"defaultSidebar"},"Configurations/Profiles/additional":{"id":"Configurations/Profiles/additional","title":"Additional Profile Settings","description":"SAS Options Settings Examples","sidebar":"defaultSidebar"},"Configurations/Profiles/index":{"id":"Configurations/Profiles/index","title":"Profile Definitions and Connection Types","description":"Profiles provide an easy way to switch between multiple SAS deployments. For SAS Viya connections, multiple Viya profiles are used to switch between compute contexts. There is no limit to the number of stored profiles you can create.","sidebar":"defaultSidebar"},"Configurations/Profiles/sas9iom":{"id":"Configurations/Profiles/sas9iom","title":"SAS 9.4 (remote - IOM) Connection Profile","description":"To use a SAS 9.4 (remote \u2013 IOM) connection type, you need to install both SAS Integration Technologies Client for Windows (ITCLIENT) and the SAS Providers for OLE DB on the client machine where VS Code is installed. The order of installation does not matter.","sidebar":"defaultSidebar"},"Configurations/Profiles/sas9local":{"id":"Configurations/Profiles/sas9local","title":"SAS 9.4 (local) Connection Profile","description":"To use a SAS 9.4 (local) connection type, you need to install both SAS Integration Technologies Client for Windows (ITCLIENT) and the SAS Providers for OLE DB on the client machine where VS Code is installed. The order of installation does not matter.","sidebar":"defaultSidebar"},"Configurations/Profiles/sas9ssh":{"id":"Configurations/Profiles/sas9ssh","title":"SAS 9.4 (remote - SSH) Connection Profile","description":"To use a SAS 9.4 (remote - SSH) connection type, your SAS server must be running on Unix or Linux. The SSH connection method uses SSH to authenticate to a SAS server and runs SAS code using Interactive Line Mode. Several authentication methods are available to create a secure connection to the SAS 9.4 server.","sidebar":"defaultSidebar"},"Configurations/Profiles/sas9stdio":{"id":"Configurations/Profiles/sas9stdio","title":"SAS 9.4 (local - stdio) Connection Profile","description":"The SAS 9.4 (local - stdio) connection type allows you to run SAS locally on your machine using standard input/output pipes (stdin/stdout/stderr) instead of SSH. This connection type provides the same interactive SAS session semantics as the SSH connection type but without network overhead.","sidebar":"defaultSidebar"},"Configurations/Profiles/viya":{"id":"Configurations/Profiles/viya","title":"SAS Viya Connection Profile","description":"Profile Anatomy","sidebar":"defaultSidebar"},"Configurations/sasLog":{"id":"Configurations/sasLog","title":"SAS Log","description":"You can customize when the SAS log is displayed in the bottom panel by using the following extension settings. These settings apply to all connection profiles:","sidebar":"defaultSidebar"},"faq":{"id":"faq","title":"Frequently Asked Questions","description":"Usage questions","sidebar":"defaultSidebar"},"Features/accessContent":{"id":"Features/accessContent","title":"Accessing SAS Content","description":"After you configure the SAS extension for a SAS Viya environment, you can access SAS Content.","sidebar":"defaultSidebar"},"Features/accessLibraries":{"id":"Features/accessLibraries","title":"Accessing Libraries and Tables","description":"After you configure the SAS extension for a SAS Viya, SAS 9.4 (local), or SAS 9.4 (remote-IOM) environment, you can access your connected libraries.","sidebar":"defaultSidebar"},"Features/accessServer":{"id":"Features/accessServer","title":"Accessing SAS Server","description":"After you configure the SAS extension for a SAS Viya environment, you can access SAS Server.","sidebar":"defaultSidebar"},"Features/errorsWarnings":{"id":"Features/errorsWarnings","title":"Fixing Errors and Warnings","description":"The Problems panel contains error and warning messages that are generated by the SAS log when you run a program. Errors and warnings in the Problems panel are not cleared until you rerun the code. The Quick Fix option enables you to remove items from the Problems panel without rerunning the code.","sidebar":"defaultSidebar"},"Features/index":{"id":"Features/index","title":"Features","description":"The SAS extension includes many features to help you access your data, write and run code, and create SAS notebooks.","sidebar":"defaultSidebar"},"Features/positron":{"id":"Features/positron","title":"Positron SAS Extension Features","description":"The Positron SAS extension adds SAS to Positron as a language with its own console. SAS code runs in that console, and its results go to the usual Positron panes: the Viewer, the Plots pane, the Data Explorer, and the Connections pane. Posit Assistant can see the results and explore SAS data.","sidebar":"defaultSidebar"},"Features/running":{"id":"Features/running","title":"Running SAS Code","description":"After you configure the SAS extension for your SAS environment, you can run your SAS program and view the log and results. The steps to connect to SAS and run your program are different for SAS Viya and SAS 9.","sidebar":"defaultSidebar"},"Features/runningTask":{"id":"Features/runningTask","title":"Running SAS Code by Task","description":"Run selected code or all code in active editor","sidebar":"defaultSidebar"},"Features/sasCodeEditing":{"id":"Features/sasCodeEditing","title":"SAS Code Editing Features","description":"SAS Syntax Highlighting","sidebar":"defaultSidebar"},"Features/sasNotebook":{"id":"Features/sasNotebook","title":"SAS Notebook","description":"SAS Notebook is an interactive notebook file that includes markdown code, executable code snippets, and corresponding rich output cells.","sidebar":"defaultSidebar"},"installation":{"id":"installation","title":"Installation","description":"Install the SAS Extension for Positron","sidebar":"defaultSidebar"},"matrix":{"id":"matrix","title":"Capabilities by Connection Type","description":"| SAS Extension for Visual Studio Code - Capabilities by Connection Type                        |      SAS Viya      | SAS 9.4 (local)  SAS 9.4 (remote - IOM) | SAS 9.4 (local - stdio) | SAS 9.4 (remote - SSH) | Notes                                                                                                                 |","sidebar":"defaultSidebar"},"README":{"id":"README","title":"SAS Extension for Positron","description":"Welcome to the SAS Extension for Positron! The SAS extension is lightweight, runs anywhere, and allows you to integrate SAS with other languages.","sidebar":"defaultSidebar"},"Workbench/Code/index":{"id":"Workbench/Code/index","title":"Scenario 3: SAS in Your R and Python Code","description":"In this scenario, users mix SAS and R, or SAS and Python, in the same code. R or Python prepares the data, SAS runs the analysis, and R or Python presents the results. The code runs in Posit Workbench sessions and in content that users publish to Posit Connect.","sidebar":"defaultSidebar"},"Workbench/Code/local":{"id":"Workbench/Code/local","title":"Local SAS Execution","description":"In this variant, SAS is installed where the R or Python code runs. saspy starts SAS as a child process and talks to it over standard input and output (STDIO). No SAS server, network connection, or sign-in is involved.","sidebar":"defaultSidebar"},"Workbench/Code/viyaOauth":{"id":"Workbench/Code/viyaOauth","title":"SAS Viya with OAuth Tokens","description":"In this variant, R and Python code sends SAS work to SAS Viya 4. Posit Workbench or Posit Connect signs the user in to SAS Logon and gives the code a SAS Viya access token. The code passes the token to saspy, swat, or sasctl and never handles a password.","sidebar":"defaultSidebar"},"Workbench/foundations":{"id":"Workbench/foundations","title":"Across All Scenarios","description":"These topics apply to every scenario. The examples come from a reference deployment, which runs Posit Workbench, Posit Connect, and SAS Viya in one Amazon EKS cluster.","sidebar":"defaultSidebar"},"Workbench/index":{"id":"Workbench/index","title":"SAS with Posit Workbench","description":"Posit Workbench and Posit Connect support several ways to bring SAS into your data science work. They differ in how closely SAS works with R and Python: side by side as separate tools, together in one editor, or mixed in the same code.","sidebar":"defaultSidebar"},"Workbench/Positron/index":{"id":"Workbench/Positron/index","title":"SAS within Positron","description":"Positron runs SAS next to R and Python. With the SAS extension, SAS gets its own console and the same Viewer, Plots pane, Connections pane, and Data Explorer as the other languages, and Posit Assistant can work with SAS code and results. For the full list, see Positron SAS Extension Features.","sidebar":"defaultSidebar"},"Workbench/Positron/localInstalled":{"id":"Workbench/Positron/localInstalled","title":"Local SAS: SAS Installed with Workbench","description":"An administrator installs SAS where Workbench sessions run, in the same way as R and Python: on the Workbench host for local sessions, or in the session image for container sessions. Positron then runs SAS in the session through the local (stdio) connection.","sidebar":"defaultSidebar"},"Workbench/Positron/remoteSsh":{"id":"Workbench/Positron/remoteSsh","title":"Remote SAS over SSH","description":"Positron connects to a SAS 9.4 server, or to a standalone SAS Analytics Pro server, over SSH. SAS runs on that server, and the session sends code and receives the log and results.","sidebar":"defaultSidebar"},"Workbench/Positron/remoteViya":{"id":"Workbench/Positron/remoteViya","title":"Remote SAS Viya","description":"Positron connects to SAS Viya over its REST APIs. SAS code runs in a SAS Viya compute session, and the extension also gives access to SAS Content, SAS server files, and, with SAS Clinical Acceleration, the Clinical Repository.","sidebar":"defaultSidebar"},"Workbench/requirements":{"id":"Workbench/requirements","title":"Requirements by Scenario","description":"This page lists what each scenario and variant needs.","sidebar":"defaultSidebar"}}}}')}}]);